function askRemove(id){
  const host = $('#impRm');
  if(!host) return;
  host.innerHTML = rmAsk(id, 'data-imprmno="' + esc(id) + '"');
  const b = host.querySelector('[data-imprmno]'); if(b) b.focus({ preventScroll:true });
  host.scrollIntoView({ block:'center' });   // both buttons in sight, above the tab bar
}

function showRemove(id){
  openSheet('Local list', 'Remove this list', '<div class="imprm">' + rmAsk(id, 'data-close') + '</div>');
  const b = $('#sheetIn [data-close]'); if(b) b.focus({ preventScroll:true });
}
